INSERT INTO `songs` VALUES (1,'1','Happy the people who refuse','David G Preston',NULL,'Jubilate Hymns','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(2,'2A','Why do all the nations rage','David G Preston',NULL,'Jubilate Hymns','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(3,'2B','Why do the nations rage and cry','Jim Sayers',NULL,'Author','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(4,'3','O Lord, how many enemies','Mollie Knight 1917-93',NULL,'Jubilate Hymns','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(5,'4','O hear my cry, my righteous God','Sing Psalms 1997','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(6,'5','O Lord, at early morning hear','Isaac Watts 1674-1748','O Lord, at early morning hear\nMy voice ascend on high;\nTo you will I address my prayer,\nTo you lift up my eye.\n\nYou are a God before whose sight\nThe wicked may not stand;\nTheir pride and falsehood, rage and spite\nShall cease at your command.\n\nBut by your mercy I may now\nWithin your house appear;\nTowards your temple I will bow\nAnd worship you with fear.\n\nLead me, O Lord, direct my feet\nIn ways of righteousness;\nMake every path of duty straight\nAnd plain before my face.\n\nFor lying lips and murderous hearts\nGreat wickedness have planned;\nLet them receive their just deserts,\nO God, by their own hand.\n\nLet all who trust you, Lord, delight\nTo see their hopes fulfilled,\nFor you surround them day and night\nWith favour as a shield.\n-+-','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(7,'6','O Lord, do not rebuke me','David G Preston','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(8,'7','From my pursuers keep me safe','David G Preston','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(9,'8','In all the earth, O Lord, our Lord','Sing Psalms 1997','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(10,'9','Your praises, Lord, with all my heart','Veronica Medd',NULL,'Author','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(11,'10','In my hour of grief or need','Timothy Dudley-Smith','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(12,'11','I\'ve found my refuge in the Lord','David G Preston','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(13,'12','Help us, O Lord, the righteous all have vanished','Andrew King','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(14,'13','How long will you forget me, Lord','Christopher Idle','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(15,'14','The fool whose heart declares in pride','Stephen Wilcockson','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(16,'15','Lord, who may venture where you dwell','David G Preston','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(17,'16','O God, my refuge, keep me safe','David G Preston','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(18,'17','Lord, hear my plea, my innocence declare','David G Preston','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(19,'18','I love you, O Lord, you alone','Christopher Idle',NULL,'author / Jubilate Hymns','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(20,'19A','The heavens declare God\'s glory','David G Preston',NULL,'author/jubilate hymns','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(21,'19B','God\'s glory fills the heavens with hymns','Carl P Daw Jr.','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(22,'20','The Lord be near us as we pray','Timothy Dudley-Smith','','','2016-10-11 08:57:00','2016-10-11 08:57:00',NULL,1,NULL,'Psalms',NULL),(23,'21','Lord, to you we lif